"""Compute every generated file in memory, then write them together."""
from . import codex, copilot, cursor, gemini, generate, manifest, modmap, plugin, plugin_evals, skills
from .config import ADAPTERS_DIR, MODULE_MAP, PACK_DIR, PLUGINS_DIR, REGISTRY, SKILLS_DIR, STARTER, read, safe_path

# Host formats generated besides the Claude Code plugins, each a module with outputs() and problems().
HOSTS = (codex, copilot, cursor, gemini)
# Folders whose every file is generated, so anything else found there is stale. In adapters/ the READMEs are sources.
GENERATED_DIRS = (PLUGINS_DIR, SKILLS_DIR, ADAPTERS_DIR, ".agents/plugins", ".cursor-plugin")
HAND_WRITTEN = ("README.md",)


def outputs(root):
    """Return (families, generated) where generated maps repository paths to bytes."""
    families = manifest.load(root)
    for role in manifest.roles(families):
        read(root, role["path"])  # a missing card stops the build before anything is written
    generated = {}
    for family in families:
        generated[f"catalog/{family['id']}/INDEX.md"] = generate.index(root, family)
    generated[STARTER] = generate.starter(root)
    generated[REGISTRY] = generate.registry(root, families)
    for family in families:
        for pack in family["packs"]:
            generated[generate.pack_path(pack)] = generate.family_pack(root, family, pack, generated)
    generated.update(skills.outputs(root, families))
    generated.update(plugin.outputs(root, families))
    generated.update(plugin_evals.outputs(root, families))
    for host in HOSTS:
        for name, data in host.outputs(root, families).items():
            if name in generated:
                raise ValueError(f"{name}: generated by two host adapters")
            generated[name] = data
    generated[MODULE_MAP] = modmap.generate(root, families, generated)
    return families, generated


def build(root):
    _, generated = outputs(root)
    destinations = {safe_path(root, name): data for name, data in generated.items()}
    for path, data in destinations.items():
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(data)
    for stale in stale_files(root, generated):
        safe_path(root, stale).unlink()
    for top in GENERATED_DIRS:
        base = root / top
        for folder in sorted(base.rglob("*"), reverse=True) if base.is_dir() else []:
            if folder.is_dir() and not any(folder.iterdir()):
                folder.rmdir()


def stale_files(root, generated):
    """Generated-looking files that no longer have a source: old packs and anything left in a generated folder."""
    found = []
    pack_dir = root / PACK_DIR
    for path in sorted(pack_dir.glob("*.md")) if pack_dir.is_dir() else []:
        found.append(path.relative_to(root).as_posix())
    for top in GENERATED_DIRS:
        base = root / top
        for path in sorted(base.rglob("*")) if base.is_dir() else []:
            relative = path.relative_to(root)
            if "results" in relative.parts[2:4] and relative.parts[2:3] == ("evals",):
                continue  # `claude plugin eval` writes its results here; .gitignore keeps them out of Git
            if (path.is_file() or path.is_symlink()) and not (top == ADAPTERS_DIR and len(relative.parts) == 3
                                                               and relative.name in HAND_WRITTEN):
                found.append(relative.as_posix())
    return [name for name in found if name not in generated]
